function specValues(kind,p){const historical=window.REAL_DATA_MODE&&p.sizeSystem==='legacy';if(kind==='colors')return [...(window.REAL_DATA_MODE?p.selectedColorIds??(historical?[]:p.colorIds):p.colorIds)];if(kind==='fits')return [...(window.REAL_DATA_MODE?p.selectedFitIds??(historical?[]:(p.fitIds||[p.fitId])):(p.fitIds||[p.fitId])).filter(Boolean)];const current=(C.group(p.groupId)?.sizes||[]).map(x=>x.id);return [...(window.REAL_DATA_MODE?p.selectedSizeIds??(historical?[]:C.sizeRecords(p).map(x=>x.id)):C.sizeRecords(p).map(x=>x.id))].filter(id=>current.includes(id))}
