  select('#pc-detail-year',()=>p.year,()=>C.years().map(id=>({id,name:id+'年'})),value=>{p.year=value},false,true,'选择年份',false);
  select('#pc-detail-season',()=>C.seasonValues(p),()=>C.seasons,values=>{p.season=(values||[]).join('、')},true,!!(p.productSchema===2),'选择季节');
  select('#pc-detail-supplier',()=>p.supplierId,()=>C.suppliers.filter(x=>!x.disabled&&x.enabled!==false).map(x=>({id:x.id,name:x.name})),value=>{p.supplierId=value},false,true,'选择供应商');
