 if(result.error){U.saveError=result.error;const rules=[[/款号/,'base','[data-edit=id]'],[/商品名称/,'base','[data-edit=name]'],[/分类/,'base','#pc-detail-category'],[/采购价/,'prices','[data-edit=purchasePrice]'],[/最低售价/,'prices','[data-edit=minimumPrice]'],[/零售价/,'prices','[data-edit=price]'],[/系统货号/,'base','[data-edit=barcodeItemCode]'],[/年份/,'base','#pc-detail-year'],[/季节/,'base','#pc-detail-season'],[/供应商/,'base','#pc-detail-supplier'],[/版型/,'specs','[data-pc=spec-edit][data-kind=fits]'],[/尺码/,'specs','#pc-detail-group'],[/颜色/,'specs','[data-pc=spec-edit][data-kind=colors]'],[/方案/,'barcodes','#pc-detail-scheme']];const hit=rules.find(x=>x[0].test(result.error));if(hit)U.tab=hit[1];window.render();$('#pc-editor-error').textContent=result.error;const target=hit&&$(hit[2]);if(target){target.setAttribute('aria-invalid','true');target.scrollIntoView({block:'center'});}message(result.error);return false}
 U.saveError='';U.edit=cl(result.product);U.editId=window.REAL_DATA_MODE?result.product.uuid||result.product.id:result.product.id;U.baseline=JSON.stringify(U.edit);history.replaceState(null,'','#product/'+encodeURIComponent(U.editId));U.route='product/'+encodeURIComponent(U.editId);message(result.barcodeNotice||'商品已保存');return true;
