async function requestDelete(kind,id){const issue=kind==='products'||window.REAL_DATA_MODE?'':C.deletionIssue(kind,id,[U.edit,U.parked?.edit]);if(issue){if(kind==='categories'){$('#pc-category-error').textContent=issue;return}return err(issue)}if(window.REAL_DATA_MODE){try{if(kind==='products')await LEGACY_REAL.checkProductDelete(id);else await LEGACY_REAL.checkProductMaster(kind,id)}catch(e){if(kind==='categories')$('#pc-category-error').textContent=e.message;else if(U.modal)err(e.message);else $('#pc-editor-error').textContent=e.message;message(e.message);return}}U.deletePending={kind,id,modal:U.modal,draft:U.modalDraft};U.modal='delete';const name={categories:'分类',colors:'颜色',fits:'版型',groups:'尺码组',seasons:'季节',products:'商品'}[kind];modal('确认删除'+name,`<p>删除该${name}后无法恢复，确定继续吗？</p>`,btn('取消','delete-cancel')+btn('确认删除','delete-confirm','','pc-danger-solid'))}
function cancelDelete(){const pending=U.deletePending;U.deletePending=null;if(!pending)return closeModal();if(pending.kind==='categories')return closeModal();U.modal=pending.modal;U.modalDraft=pending.draft;if(pending.kind==='groups')drawGroup();else {const draft=pending.draft;openDict(pending.id);U.modalDraft=draft;const f=$('#pc-dict-form');for(const key of ['name','code'])if(f.elements[key])f.elements[key].value=draft[key]||''}}
async function confirmDelete(){const p=U.deletePending;if(!p)return;if(p.kind==='products'){try{if(window.REAL_DATA_MODE)await LEGACY_REAL.deleteProduct(p.id);else{const product=detailProduct(p.id);if(D.total(product)!==0)throw Error('库存不为 0，无法删除');D.products.splice(D.products.indexOf(product),1)}}catch(e){return err(e.message)}U.deletePending=null;closeModal();U.edit=null;U.editId=null;navigate('products',false);message('商品已删除');return}if(window.REAL_DATA_MODE){try{await LEGACY_REAL.changeProductMaster(p.kind,p.id,'delete');}catch(e){return err(e.message)}}else{const r=C.deleteMaster(p.kind,p.id,[U.edit,U.parked?.edit]);if(r.error){cancelDelete();if(p.kind==='categories')$('#pc-category-error').textContent=r.error;else err(r.error);return}}U.deletePending=null;closeModal();if(p.kind==='categories'){U.categoryId='all';U.categoryDraft=null;U.categoryUndo=null;U.filter.categories=U.filter.categories.filter(id=>id!==p.id);U.filterDraft.categories=U.filterDraft.categories.filter(id=>id!==p.id);syncCategories()}window.render();message('已删除')}
function descendant(id,ancestor){let cur=C.categories.find(c=>c.id===id),seen=new Set();while(cur&&!seen.has(cur.id)){if(cur.parent===ancestor)return true;seen.add(cur.id);cur=C.categories.find(c=>c.id===cur.parent)}return false}
async function saveCategory(){const c=U.categoryDraft;if(c.id==='all')return true;if(!c.name.trim()){message('分类名称必填');return false}if(c.parent===c.id||descendant(c.parent,c.id)){message('不能把分类移到自身或子分类下面');return false}if(C.categories.some(x=>x.id!==c.id&&x.parent===c.parent&&x.name===c.name.trim())){message('同级分类名称不能重复');return false}if(!C.categories.some(x=>x.id===c.parent)){message('请选择有效父级');return false}if(c.parent!=='all'&&!C.standardParents().some(x=>x.id===c.parent))return err('分类只使用一级和二级结构');const data={...c,name:c.name.trim(),order:+c.order,standard:true,leaf:c.parent!=='all'};delete data.isNew;if(window.REAL_DATA_MODE){try{await LEGACY_REAL.changeProductMaster('categories',c.id,'save',data)}catch(e){err(e.message);return false}}else{const old=C.categories.find(x=>x.id===c.id);old?Object.assign(old,data):C.categories.push(data)}U.categoryId=c.id;U.categoryDraft=cl(data);U.categoryBase=JSON.stringify(data);U.expanded.add(c.parent);syncCategories();message('分类已保存');return true}
