function imageManager(){return '<div id="pc-photo-app"></div>'}
async function ingestImages(files,ctx){
 const {role,colorId='',replaceId='',owner}=ctx;
 if(!files?.length||owner!==U.edit)return;
 const multi=['主图','白底图','吊牌图','详情图'].includes(role)&&!replaceId;
 const selected=multi?Array.from(files):[files[0]];
 if(selected.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024))return message('请选择 8 MB 以内的 PNG、JPEG 或 WebP 图片');
 U.pendingImages=(U.pendingImages||0)+1;
 try{
  const loaded=await Promise.all(selected.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const probe=new Image();probe.onload=()=>resolve({id:'photo-'+crypto.randomUUID(),name:f.name,url:reader.result,role,colorId});probe.onerror=reject;probe.src=reader.result};reader.onerror=reject;reader.readAsDataURL(f)})));
  if(owner!==U.edit)return;
  if(replaceId){const index=owner.images.findIndex(im=>im.id===replaceId);if(index<0)return;owner.images.splice(index,1,loaded[0])}
  else if(role==='颜色配图'){owner.images=owner.images.filter(im=>im.role!==role||im.colorId!==colorId);owner.images.push(loaded[0])}
  else owner.images.push(...loaded);
  if(U.tab==='images')window.render();message('已添加到商品草稿');
 }catch{message('图片无法读取，请选择有效的图片文件')}
 finally{U.pendingImages--}
}
